    environment.commit {
        if (_uiState.value.subject == subject) {
            locallyModifiedFields = locallyModifiedFields + VideoEngagementField.FAVORITE
            _uiState.value = _uiState.value.copy(favoriteCount = count)
            applied = true
        }
    }
    return applied
